package cn.bugstack.ai.infrastructure.adapter.repository.attachment;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;

/** Private directory storage. Keys are generated by the service and validated; uploaded names never reach the path. */
final class LocalChatFileStorage implements ChatFileStorage {

    static final Pattern KEY = Pattern.compile("[a-z0-9-]{1,40}/[a-z0-9-]{1,40}/[0-9a-f]{64}");

    private final Path root;

    LocalChatFileStorage(Path root) {
        this.root = root.toAbsolutePath().normalize();
    }

    @Override public String provider() { return "LOCAL"; }

    @Override public String bucket() { return ""; }

    @Override
    public void put(String objectKey, Path file, String mimeType) throws IOException {
        Path target = resolve(objectKey, true);
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) return; // same owner + sha256: identical content
        Path pending = target.resolveSibling(target.getFileName() + ".pending");
        Files.copy(file, pending, StandardCopyOption.REPLACE_EXISTING);
        Files.move(pending, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
    }

    @Override
    public void download(String objectKey, Path target) throws IOException {
        Files.copy(resolve(objectKey, false), target, StandardCopyOption.REPLACE_EXISTING);
    }

    @Override
    public InputStream open(String objectKey) throws IOException {
        return Files.newInputStream(resolve(objectKey, false));
    }

    @Override
    public InputStream read(String objectKey) throws IOException {
        return open(objectKey);
    }

    @Override
    public String signedDownloadUrl(String objectKey, String fileName) {
        return null;
    }

    @Override
    public void delete(String objectKey) throws IOException {
        Files.deleteIfExists(resolve(objectKey, false));
    }

    /** Local path of the stored original; parsing reads it in place. */
    Path path(String objectKey) throws IOException {
        return resolve(objectKey, false);
    }

    private Path resolve(String objectKey, boolean create) throws IOException {
        if (objectKey == null || !KEY.matcher(objectKey).matches()) throw new IOException("Invalid attachment key");
        Path path = root.resolve(objectKey).normalize();
        if (!path.startsWith(root)) throw new IOException("Invalid attachment key");
        if (create) Files.createDirectories(path.getParent());
        for (Path p = path; p != null && p.startsWith(root); p = p.getParent()) {
            if (Files.isSymbolicLink(p)) throw new IOException("Symlink rejected");
        }
        return path;
    }
}
